// Release gate for the 2.5.0 "align to latest toolchain" contract.
//
// Goldens prove the generated bytes did not change; they do NOT prove the
// generated code still COMPILES. analyzer 14.6 replaced `undefined_getter`
// with the `undefined_*_read` / `undefined_*_write` family, and that is
// exactly the class of breakage that only shows up when the emitted source
// is re-analyzed (zuraffa#1980). This gate drives the real pipeline
// (resolved ClassElement -> ClassAnalyzer -> Orchestrator.generate) over one
// fixture library per feature family, writes the output as the generated
// part, and asserts the analyzer — the version pinned in pubspec.lock, in
// process — reports ZERO diagnostics for every fixture.
//
// The fixtures live in a temp dir under test/ (each run gets its own), so
// the gate is concurrency-safe and stays in the default fast tier: no
// build_runner, no child `dart analyze` process.

import 'dart:io';

import 'package:analyzer/dart/analysis/analysis_context_collection.dart';
import 'package:analyzer/dart/analysis/results.dart';
import 'package:analyzer/dart/element/element.dart';
import 'package:source_gen/source_gen.dart';
import 'package:test/test.dart';
import 'package:zorphy/src/analysis/annotation_parser.dart';
import 'package:zorphy/src/analysis/class_analyzer.dart';
import 'package:zorphy/src/analysis/class_graph.dart';
import 'package:zorphy/src/models/generation_config.dart';
import 'package:zorphy/src/orchestrator.dart';

const _zorphyChecker = TypeChecker.fromUrl(
  'package:zorphy_annotation/src/annotations.dart#Zorphy',
);

/// One fixture library per feature family, all with JSON generation OFF so the
/// gate asserts a hard zero: every remaining diagnostic would be zorphy's own.
const _fixtures = <String, String>{
  'basic': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'basic.zorphy.dart';

@Zorphy()
abstract class \$User {
  String get id;
  String get name;
  int get age;
}
''',
  'full_preset': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'full_preset.zorphy.dart';

@Zorphy(preset: ZorphyPreset.full)
abstract class \$Product {
  String get id;
  String get title;
  double get price;
  int? get stock;
}
''',
  'inheritance': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'inheritance.zorphy.dart';

@Zorphy()
abstract class \$\$Animal {
  String get id;
  String get name;
}

@Zorphy()
abstract class \$Dog implements \$\$Animal {
  String get breed;
}
''',
  'enum_field': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'enum_field.zorphy.dart';

enum TaskStatus { open, inProgress, done }

@Zorphy()
abstract class \$Task {
  String get id;
  TaskStatus get status;
  List<TaskStatus>? get history;
}
''',
  // arrrrny/zorphy#159: a sealed base with `explicitSubTypes` whose subtypes
  // do not generate JSON must not emit the changeTo extension — its body
  // round-trips through toJson/fromJson the subtypes do not have. With the fix
  // in, the generated part analyzes clean, so this is a strict fixture.
  'sealed_no_json': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'sealed_no_json.zorphy.dart';

@Zorphy(explicitSubTypes: [\$Circle])
abstract class \$\$Shape {
  double get area;
}

@Zorphy()
abstract class \$Circle implements \$\$Shape {
  double get radius;
}
''',
};

/// JSON-emitting fixtures. Their generated code calls `_$XToJson` /
/// `_$XFromJson`, which live in the json_serializable part (`.g.dart`) that a
/// consumer build produces — so `_isJsonPartSymbol` diagnostics are the only
/// ones these may report.
const _jsonFixtures = <String, String>{
  'json_basic': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'json_basic.zorphy.dart';

@Zorphy(generateJson: true)
abstract class \$Profile {
  String get id;
  String get displayName;
  int? get score;
}
''',
  'json_sealed': '''
import 'package:zorphy_annotation/zorphy_annotation.dart';

part 'json_sealed.zorphy.dart';

@Zorphy(generateJson: true, explicitSubTypes: [\$CreditCard])
abstract class \$\$Payment {
  String get id;
}

@Zorphy(generateJson: true)
abstract class \$CreditCard implements \$\$Payment {
  String get last4;
}
''',
};

/// Generates the `.zorphy.dart` part body for every `@Zorphy` class declared
/// in the library at [libraryPath].
Future<Map<String, String>> _generateLibrary(String libraryPath) async {
  final collection = AnalysisContextCollection(
    includedPaths: [Directory(libraryPath).parent.path],
  );
  final outputs = <String, String>{};
  try {
    final result =
        await collection
                .contextFor(libraryPath)
                .currentSession
                .getResolvedUnit(libraryPath)
            as ResolvedUnitResult;
    final graph = ClassGraph.fromLibraryClasses(
      result.libraryElement.classes.toList(),
      library: result.libraryElement,
    );
    for (final element in result.libraryElement.classes) {
      final annotation = _zorphyChecker.firstAnnotationOf(element);
      if (annotation == null) continue;
      final annotationReader = ConstantReader(annotation);

      final metadata = ClassAnalyzer.analyze(
        element,
        annotationReader,
        graph.annotated,
        graph.classesInExplicitSubtypes,
      );

      final ownFields = element.children
          .whereType<FieldElement>()
          .where((f) => f.name != 'hashCode' && f.name != 'runtimeType')
          .map((f) => f.name ?? '')
          .toSet();
      final config = GenerationConfig.fromAnnotationOptions(
        AnnotationParser.parse(annotationReader),
        outputExtension: '.zorphy.dart',
        factoryMethods: metadata.factoryMethods,
        ownFields: ownFields,
      );

      outputs[element.displayName] = Orchestrator.generate(
        element,
        annotationReader,
        graph.annotated,
        config,
        graph.classesInExplicitSubtypes,
      );
    }
  } finally {
    await collection.dispose();
  }
  return outputs;
}

/// Every diagnostic the analyzer reports for [libraryPaths] and their
/// generated parts, formatted as `<file>: <code> — <message>`.
Future<List<String>> _diagnostics(List<String> libraryPaths) async {
  final collection = AnalysisContextCollection(
    includedPaths: [Directory(libraryPaths.first).parent.path],
  );
  final diagnostics = <String>[];
  try {
    for (final path in libraryPaths) {
      final library =
          await collection
                  .contextFor(path)
                  .currentSession
                  .getResolvedLibrary(path)
              as ResolvedLibraryResult;
      for (final unit in library.units) {
        for (final diagnostic in unit.diagnostics) {
          diagnostics.add(
            '${path.split('/').last}: '
            '${diagnostic.diagnosticCode.lowerCaseName} — '
            '${diagnostic.problemMessage.messageText(includeUrl: false)}',
          );
        }
      }
    }
  } finally {
    await collection.dispose();
  }
  return diagnostics;
}

void main() {
  group('analyze-clean gate (2.5.0)', () {
    late Directory fixtureDir;
    late Map<String, Map<String, String>> generated;

    setUpAll(() async {
      final root = Directory('test/.analyze_clean_tmp').absolute
        ..createSync(recursive: true);
      fixtureDir = root.createTempSync('fixture_');

      generated = {};
      for (final entry in {..._fixtures, ..._jsonFixtures}.entries) {
        final path = '${fixtureDir.path}/${entry.key}.dart';
        File(path).writeAsStringSync(entry.value);
        final outputs = await _generateLibrary(path);
        expect(
          outputs,
          isNotEmpty,
          reason: '${entry.key} has no @Zorphy class to generate from',
        );
        generated[entry.key] = outputs;
        File('${fixtureDir.path}/${entry.key}.zorphy.dart').writeAsStringSync(
          "part of '${entry.key}.dart';\n\n${outputs.values.join('\n\n')}",
        );
      }
    });

    tearDownAll(() {
      if (fixtureDir.existsSync()) fixtureDir.deleteSync(recursive: true);
      final tmp = Directory('test/.analyze_clean_tmp');
      if (tmp.existsSync() && tmp.listSync().isEmpty) tmp.deleteSync();
    });

    test('every fixture library produced generated output', () {
      expect(generated.keys.toSet(), {
        ..._fixtures.keys,
        ..._jsonFixtures.keys,
      });
    });

    test('non-JSON generated output analyzes with zero diagnostics', () async {
      final diagnostics = await _diagnostics(
        _fixtures.keys.map((n) => '${fixtureDir.path}/$n.dart').toList(),
      );
      expect(
        diagnostics,
        isEmpty,
        reason:
            'generated .zorphy.dart must analyze clean under the pinned '
            'analyzer; diagnostics:\n${diagnostics.join('\n')}',
      );
    });

    test(
      'JSON generated output only awaits the json_serializable part',
      () async {
        final diagnostics = await _diagnostics(
          _jsonFixtures.keys.map((n) => '${fixtureDir.path}/$n.dart').toList(),
        );
        final unexpected = diagnostics
            .where((d) => !_isJsonPartSymbol(d))
            .toList();
        expect(
          unexpected,
          isEmpty,
          reason:
              r'only the json_serializable `_$XToJson`/`_$XFromJson` part '
              'symbols may be unresolved (a consumer build generates them); '
              'anything else is a zorphy defect. diagnostics:\n'
              '${diagnostics.join('\n')}',
        );
      },
    );
  });
}

/// Whether [diagnostic] is an unresolved reference to a json_serializable
/// part symbol (`_$XToJson` / `_$XFromJson`), which no zorphy output defines.
///
/// Under analyzer 14.6+ these surface as `undefined_method`; under analyzer
/// 13.x (still in the CI compat matrix and resolvable for Dart 3.11/3.12
/// consumers) they surface as the pre-14.6 `undefined_getter`.
bool _isJsonPartSymbol(String diagnostic) {
  if (!diagnostic.contains('undefined_') &&
      !diagnostic.contains("isn't defined")) {
    return false;
  }
  final match = RegExp(r"'(_\$[A-Za-z0-9_]+)'").firstMatch(diagnostic);
  final name = match?.group(1);
  if (name == null) return false;
  return name.endsWith('ToJson') || name.endsWith('FromJson');
}
